def add_reciprocal_link(path: Path, sentence: str) -> None:
    text = path.read_text(encoding="utf-8")
    if sentence in text:
        return
    match = re.search(r'(<p class="article-opening">.*?</p>)', text, flags=re.S)
    if not match:
        raise RuntimeError(f"Could not find opening paragraph in {path}")
    text = text[:match.end()] + sentence + text[match.end():]
    path.write_text(text, encoding="utf-8", newline="\n")


def main() -> None:
    for item in ARTICLES:
        document = base.page(item["url"], item["seo"], item["title"], item["description"], item["deck"], item["department"], item["topic"], item["hero"], item["alt"], item["body"], "BlogPosting", item["words"], item["keywords"])
        destination = ROOT / item["url"].strip("/") / "index.html"
        destination.parent.mkdir(parents=True, exist_ok=True)
        destination.write_text(document, encoding="utf-8", newline="\n")
        print("Built", destination.relative_to(ROOT))

    catalogue_path = ROOT / "content" / "articles.json"
    current = json.loads(catalogue_path.read_text(encoding="utf-8"))
    additions = []
    for item in ARTICLES:
        additions.append({"title": html.unescape(item["title"]), "seoTitle": html.unescape(item["seo"]), "department": item["department"].lower(), "topic": item["topic"].lower().replace(" ", "-"), "published": PUBLISHED, "readingMinutes": round(item["words"] / 195), "readingWordsPerMinute": 195, "url": item["url"], "excerpt": html.unescape(item["deck"]), "metaDescription": item["description"], "image": {"webp": f'{item["hero"]}.webp', "fallback": f'{item["hero"]}.jpg', "alt": item["alt"], "width": 1536, "height": 1024}, "articleSection": item["topic"], "breadcrumbTopic": True})
